<script setup lang="ts">import {Head,useForm} from '@inertiajs/vue3';import PageHeader from '@/Components/Shared/PageHeader.vue';import {Button} from '@/components/ui/button';import {Input} from '@/components/ui/input';const p=defineProps<{advertiser:any|null}>();const f=useForm({name:p.advertiser?.name??'',status:p.advertiser?.status??'active',website_url:p.advertiser?.website_url??'',billing_email:p.advertiser?.billing_email??'',contact_name:p.advertiser?.contact_name??'',contact_email:p.advertiser?.contact_email??'',contact_phone:p.advertiser?.contact_phone??'',billing_address:p.advertiser?.billing_address??'',notes:p.advertiser?.notes??''});const save=()=>p.advertiser?f.put(`/admin/advertisers/${p.advertiser.id}`):f.post('/admin/advertisers');</script><template><Head :title="advertiser?'Edit Advertiser':'Add Advertiser'"/><form class="space-y-6 p-6" @submit.prevent="save"><PageHeader :title="advertiser?'Edit Advertiser':'Add Advertiser'" description="Organization, contact, and billing information."/><div class="grid gap-4 rounded-xl border p-5 md:grid-cols-2"><label>Name<Input v-model="f.name"/></label><label>Status<select v-model="f.status" class="h-10 w-full rounded-md border bg-background px-3"><option>active</option><option>inactive</option><option>prospect</option></select></label><label>Website<Input v-model="f.website_url"/></label><label>Billing email<Input v-model="f.billing_email" type="email"/></label><label>Contact name<Input v-model="f.contact_name"/></label><label>Contact email<Input v-model="f.contact_email" type="email"/></label><label>Contact phone<Input v-model="f.contact_phone"/></label><label class="md:col-span-2">Billing address<textarea v-model="f.billing_address" class="min-h-24 w-full rounded-md border bg-background p-3"/></label><label class="md:col-span-2">Internal notes<textarea v-model="f.notes" class="min-h-24 w-full rounded-md border bg-background p-3"/></label></div><Button :disabled="f.processing">Save Advertiser</Button></form></template>